const s = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const online = Number(msg.statusCode) === 200 && !msg.error;
const uptimeSeconds = Math.max(0, Math.floor(Number(s.uptime || 0) / 1000));
const days = Math.floor(uptimeSeconds / 86400);
const hours = Math.floor((uptimeSeconds % 86400) / 3600);
const minutes = Math.floor((uptimeSeconds % 3600) / 60);
const networkMode = s.wifiConnected ? 'Client' : (s.softAPActive ? 'Access Point' : 'Disconnected');
const protocol = Number(s.liveProtocol) === 1 ? 'sACN' : 'Art-Net';
const direction = Number(s.direction) === 1 ? 'DMX → Network' : 'Network → DMX';
msg.payload = {
    online,
    name: online ? (s.name || 'uNode') : 'uNode unavailable',
    chipId: online ? (s.chipId || 'N/A') : 'N/A',
    firmware: online ? (s.firmware || 'N/A') : 'N/A',
    ip: online ? (s.ip || 'N/A') : '2.0.0.1',
    networkMode: online ? networkMode : 'Disconnected',
    stations: Number(s.softAPStations || 0),
    protocol: online ? protocol : 'N/A',
    direction: online ? direction : 'N/A',
    universe: online ? Number(s.universe || 0) : 'N/A',
    uptime: online ? `${days}d ${hours}h ${minutes}m` : 'N/A',
    heap: online ? `${Math.round(Number(s.freeHeap || 0) / 1024)} KiB` : 'N/A',
    heapWarning: Boolean(s.heapWarningActive),
    bootCount: online ? Number(s.bootCount || 0) : 'N/A',
    resetReason: online ? (s.resetReason || 'N/A') : (msg.error && msg.error.message ? msg.error.message : 'No response'),
    artnetPackets: online ? Number(s.artnetPackets || 0) : 'N/A',
    sacnPackets: online ? Number(s.sacnPackets || 0) : 'N/A',
    dmxFrames: online ? Number(s.dmxFrames || 0) : 'N/A',
    updated: new Date().toLocaleString('en-GB')
};
return msg;

const request = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
if (request.action === 'stop') {
    return [null, { payload: '' }, { payload: { running: true, state: 'cancelling', profile: request.profile || '', duration: Number(request.duration || 0), exitCode: null } }];
}
const profile = request.profile;
if (profile === 'regression') {
    const useRp2040 = Boolean(request.rp2040 || request.button || request.reset);
    const flags = [];
    if (useRp2040) flags.push('rp2040');
    if (request.button) flags.push('button');
    if (request.reset) flags.push('reset');
    if (request.soak) flags.push('soak');
    if (request.ota) flags.push(request.otaProfile === 'legacy' ? 'ota-legacy' : 'ota-normal');
    msg.payload = `regression ${flags.length ? flags.join(',') : 'none'}`;
    msg.topic = 'start-test';
    return [msg, null, { payload: { running: true, state: 'starting', profile, duration: 0, exitCode: null, options: flags.join(',') } }];
}
const duration = Math.floor(Number(request.duration));
const allowedDurations = [300, 900, 3600, 14400, 28800];
if (!['host', 'dmx'].includes(profile) || !allowedDurations.includes(duration)) {
    return [null, null, { payload: { running: false, state: 'error', message: 'Invalid test profile or duration' } }];
}
msg.payload = `${profile} ${duration}`;
msg.topic = 'start-test';
return [msg, null, { payload: { running: true, state: 'starting', profile, duration, exitCode: null } }];

try {
    const text = Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : String(msg.payload || '');
    msg.payload = JSON.parse(text.trim());
} catch (error) {
    msg.payload = { running: false, state: 'error', message: `Status read failed: ${error.message}` };
}
return msg;

const r = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const clean = { action: r.action };
const validVersion = value => /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/.test(String(value || ''));
const validProfile = value => ['normal','legacy'].includes(value);
if (r.action === 'update') {
    if (!/^uNode_[0-9A-Fa-f]{6}$/.test(String(r.ssid || ''))) return [null, { payload: { running:false, state:'error', message:'Invalid uNode SSID', progress:0 } }];
    if (!validVersion(r.version)) return [null, { payload: { running:false, state:'error', message:'Invalid release version', progress:0 } }];
    if (!validProfile(r.profile) || !['firmware','littlefs','both'].includes(r.components)) return [null, { payload: { running:false, state:'error', message:'Invalid update selection', progress:0 } }];
    Object.assign(clean, { ssid:r.ssid, version:r.version, profile:r.profile, components:r.components, password:String(r.password || '').slice(0,128) });
} else if (r.action === 'initial-flash') {
    if (!validVersion(r.version) || !validProfile(r.profile)) return [null, { payload: { running:false, state:'error', message:'Invalid initial-flash release', progress:0 } }];
    const port = String(r.port || '');
    if (!port || port.length > 256 || !port.startsWith('/dev/')) return [null, { payload: { running:false, state:'error', message:'Invalid serial programmer', progress:0 } }];
    Object.assign(clean, { port, version:r.version, profile:r.profile, eraseAll:r.eraseAll === true });
} else if (r.action !== 'scan') {
    return [null, { payload: { running:false, state:'error', message:'Unknown updater action', progress:0 } }];
}
const encoded = Buffer.from(JSON.stringify(clean), 'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
msg.payload = encoded;
const labels = { scan:'Starting uNode AP scan', update:'Starting verified OTA update', 'initial-flash':'Starting verified initial USB flash' };
return [msg, { payload: { running:true, state:r.action === 'initial-flash' ? 'flashing' : (r.action === 'scan' ? 'scanning' : 'updating'), message:labels[r.action], progress:1, nodes:[], releases:[] } }];

try {
  const text = Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : String(msg.payload || '');
  msg.payload = JSON.parse(text.trim());
} catch (error) {
  msg.payload = { running:false, state:'error', message:`Updater status failed: ${error.message}`, progress:0, nodes:[], releases:[] };
}
return msg;
